package com.hostel.hostelmanagement.entity; import com.hostel.hostelmanagement.enums.RoomStatus; import jakarta.persistence.*; @Entity @Table(name="rooms") public class Room { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true) String roomNumber; String blockName; int capacity; int occupied; @Enumerated(EnumType.STRING) RoomStatus status=RoomStatus.AVAILABLE; public Room(){} public Long getId(){return id;} public String getRoomNumber(){return roomNumber;} public String getBlockName(){return blockName;} public int getCapacity(){return capacity;} public int getOccupied(){return occupied;} public RoomStatus getStatus(){return status;} public void setId(Long v){id=v;} public void setRoomNumber(String v){roomNumber=v;} public void setBlockName(String v){blockName=v;} public void setCapacity(int v){capacity=v;} public void setOccupied(int v){occupied=v;} public void setStatus(RoomStatus v){status=v;} }